// Port of PyYAML's parser.py — an LL(1) recursive-descent parser driven by an
// explicit state machine.
//
// stream            ::= STREAM-START implicit_document? explicit_document* STREAM-END
// implicit_document ::= block_node DOCUMENT-END*
// explicit_document ::= DIRECTIVE* DOCUMENT-START block_node? DOCUMENT-END*
// block_node_or_indentless_sequence ::=
//                       ALIAS
//                     | properties (block_content | indentless_block_sequence)?
//                     | block_content
//                     | indentless_block_sequence
// block_node        ::= ALIAS | properties block_content? | block_content
// flow_node         ::= ALIAS | properties flow_content? | flow_content
// properties        ::= TAG ANCHOR? | ANCHOR TAG?
// block_content     ::= block_collection | flow_collection | SCALAR
// flow_content      ::= flow_collection | SCALAR
// block_collection  ::= block_sequence | block_mapping
// flow_collection   ::= flow_sequence | flow_mapping
// block_sequence    ::= BLOCK-SEQUENCE-START (BLOCK-ENTRY block_node?)* BLOCK-END
// indentless_sequence   ::= (BLOCK-ENTRY block_node?)+
// block_mapping     ::= BLOCK-MAPPING_START
//                       ((KEY block_node_or_indentless_sequence?)?
//                       (VALUE block_node_or_indentless_sequence?)?)*
//                       BLOCK-END
// flow_sequence     ::= FLOW-SEQUENCE-START
//                       (flow_sequence_entry FLOW-ENTRY)*
//                       flow_sequence_entry?
//                       FLOW-SEQUENCE-END
// flow_sequence_entry   ::= flow_node | KEY flow_node? (VALUE flow_node?)?
// flow_mapping      ::= FLOW-MAPPING-START
//                       (flow_mapping_entry FLOW-ENTRY)*
//                       flow_mapping_entry?
//                       FLOW-MAPPING-END
// flow_mapping_entry    ::= flow_node | KEY flow_node? (VALUE flow_node?)?
//
// FIRST sets:
//
// stream: { STREAM-START }
// explicit_document: { DIRECTIVE DOCUMENT-START }
// implicit_document: FIRST(block_node)
// block_node: { ALIAS TAG ANCHOR SCALAR BLOCK-SEQUENCE-START
//               BLOCK-MAPPING-START FLOW-SEQUENCE-START FLOW-MAPPING-START }
// flow_node: { ALIAS ANCHOR TAG SCALAR FLOW-SEQUENCE-START FLOW-MAPPING-START }
// block_content: { BLOCK-SEQUENCE-START BLOCK-MAPPING-START
//                  FLOW-SEQUENCE-START FLOW-MAPPING-START SCALAR }
// flow_content: { FLOW-SEQUENCE-START FLOW-MAPPING-START SCALAR }
// block_collection: { BLOCK-SEQUENCE-START BLOCK-MAPPING-START }
// flow_collection: { FLOW-SEQUENCE-START FLOW-MAPPING-START }
// block_sequence: { BLOCK-SEQUENCE-START }
// block_mapping: { BLOCK-MAPPING-START }
// block_node_or_indentless_sequence: { ALIAS ANCHOR TAG SCALAR
//        BLOCK-SEQUENCE-START BLOCK-MAPPING-START FLOW-SEQUENCE-START
//        FLOW-MAPPING-START BLOCK-ENTRY }
// indentless_sequence: { ENTRY }
// flow_collection: { FLOW-SEQUENCE-START FLOW-MAPPING-START }
// flow_sequence: { FLOW-SEQUENCE-START }
// flow_mapping: { FLOW-MAPPING-START }
// flow_sequence_entry: { ALIAS ANCHOR TAG SCALAR FLOW-SEQUENCE-START
//                        FLOW-MAPPING-START KEY }
// flow_mapping_entry: { ALIAS ANCHOR TAG SCALAR FLOW-SEQUENCE-START
//                       FLOW-MAPPING-START KEY }

import { ParserError } from './errors.mjs';
import {
  DirectiveToken, DocumentStartToken, DocumentEndToken, StreamEndToken,
  BlockSequenceStartToken, BlockMappingStartToken, BlockEndToken,
  FlowSequenceStartToken, FlowMappingStartToken, FlowSequenceEndToken,
  FlowMappingEndToken, KeyToken, ValueToken, BlockEntryToken, FlowEntryToken,
  AliasToken, AnchorToken, TagToken, ScalarToken,
} from './tokens.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';

export const DEFAULT_TAGS = new Map([
  ['!', '!'],
  ['!!', 'tag:yaml.org,2002:'],
]);

// Python's %r for the ASCII strings that reach these messages (token ids and
// tag handles): prefer single quotes, switch to double if the value has one.
function repr(s) {
  const q = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = q;
  for (const ch of s) {
    if (ch === '\\') out += '\\\\';
    else if (ch === q) out += '\\' + ch;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return out + q;
}

export const ParserMixin = (Base) => class extends Base {
  constructor(...args) {
    super(...args);
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = this.parseStreamStart;
  }

  dispose() {
    // Reset the state attributes (to clear self-references)
    this.states = [];
    this.state = null;
  }

  checkEvent(...choices) {
    // Check the type of the next event.
    if (this.currentEvent === null) {
      if (this.state) this.currentEvent = this.state.call(this);
    }
    if (this.currentEvent !== null) {
      if (choices.length === 0) return true;
      for (const choice of choices) {
        if (this.currentEvent instanceof choice) return true;
      }
    }
    return false;
  }

  peekEvent() {
    // Get the next event.
    if (this.currentEvent === null) {
      if (this.state) this.currentEvent = this.state.call(this);
    }
    return this.currentEvent;
  }

  getEvent() {
    // Get the next event and proceed further.
    if (this.currentEvent === null) {
      if (this.state) this.currentEvent = this.state.call(this);
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  parseStreamStart() {
    // Parse the stream start.
    const token = this.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark, token.encoding);

    // Prepare the next state.
    this.state = this.parseImplicitDocumentStart;

    return event;
  }

  parseImplicitDocumentStart() {
    // Parse an implicit document.
    if (!this.checkToken(DirectiveToken, DocumentStartToken, StreamEndToken)) {
      this.tagHandles = DEFAULT_TAGS;
      const token = this.peekToken();
      const startMark = token.startMark;
      const endMark = startMark;
      const event = new DocumentStartEvent(startMark, endMark, false);

      // Prepare the next state.
      this.states.push(this.parseDocumentEnd);
      this.state = this.parseBlockNode;

      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    // Parse any extra document end indicators.
    while (this.checkToken(DocumentEndToken)) this.getToken();

    // Parse an explicit document.
    let event;
    if (!this.checkToken(StreamEndToken)) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken(DocumentStartToken)) {
        throw new ParserError(null, null,
          `expected '<document start>', but found ${repr(this.peekToken().id)}`,
          this.peekToken().startMark);
      }
      token = this.getToken();
      const endMark = token.endMark;
      event = new DocumentStartEvent(startMark, endMark, true, version, tags);
      this.states.push(this.parseDocumentEnd);
      this.state = this.parseDocumentContent;
    } else {
      // Parse the end of the stream.
      const token = this.getToken();
      event = new StreamEndEvent(token.startMark, token.endMark);
      if (this.states.length) throw new Error('AssertionError: not self.states');
      if (this.marks.length) throw new Error('AssertionError: not self.marks');
      this.state = null;
    }
    return event;
  }

  parseDocumentEnd() {
    // Parse the document end.
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = startMark;
    let explicit = false;
    if (this.checkToken(DocumentEndToken)) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    const event = new DocumentEndEvent(startMark, endMark, explicit);

    // Prepare the next state.
    this.state = this.parseDocumentStart;

    return event;
  }

  parseDocumentContent() {
    if (this.checkToken(DirectiveToken, DocumentStartToken, DocumentEndToken,
      StreamEndToken)) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = new Map();
    while (this.checkToken(DirectiveToken)) {
      const token = this.getToken();
      if (token.name === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null,
            'found duplicate YAML directive', token.startMark);
        }
        const [major] = token.value;
        if (Number(major) !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark);
        }
        this.yamlVersion = token.value;
      } else if (token.name === 'TAG') {
        const [handle, prefix] = token.value;
        if (this.tagHandles.has(handle)) {
          throw new ParserError(null, null,
            `duplicate tag handle ${repr(handle)}`, token.startMark);
        }
        this.tagHandles.set(handle, prefix);
      }
    }
    let value;
    if (this.tagHandles.size) value = [this.yamlVersion, new Map(this.tagHandles)];
    else value = [this.yamlVersion, null];
    for (const key of DEFAULT_TAGS.keys()) {
      if (!this.tagHandles.has(key)) this.tagHandles.set(key, DEFAULT_TAGS.get(key));
    }
    return value;
  }

  parseBlockNode() {
    return this.parseNode(true);
  }

  parseFlowNode() {
    return this.parseNode();
  }

  parseBlockNodeOrIndentlessSequence() {
    return this.parseNode(true, true);
  }

  parseNode(block = false, indentlessSequence = false) {
    let event;
    if (this.checkToken(AliasToken)) {
      const token = this.getToken();
      event = new AliasEvent(token.value, token.startMark, token.endMark);
      this.state = this.states.pop();
    } else {
      let anchor = null;
      let tag = null;
      let startMark = null;
      let endMark = null;
      let tagMark = null;
      if (this.checkToken(AnchorToken)) {
        let token = this.getToken();
        startMark = token.startMark;
        endMark = token.endMark;
        anchor = token.value;
        if (this.checkToken(TagToken)) {
          token = this.getToken();
          tagMark = token.startMark;
          endMark = token.endMark;
          tag = token.value;
        }
      } else if (this.checkToken(TagToken)) {
        let token = this.getToken();
        startMark = token.startMark;
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
        if (this.checkToken(AnchorToken)) {
          token = this.getToken();
          endMark = token.endMark;
          anchor = token.value;
        }
      }
      if (tag !== null) {
        const [handle, suffix] = tag;
        if (handle !== null) {
          if (!this.tagHandles.has(handle)) {
            throw new ParserError('while parsing a node', startMark,
              `found undefined tag handle ${repr(handle)}`, tagMark);
          }
          tag = this.tagHandles.get(handle) + suffix;
        } else {
          tag = suffix;
        }
      }
      // PyYAML keeps the non-specific-tag check commented out here.
      if (startMark === null) {
        startMark = this.peekToken().startMark;
        endMark = startMark;
      }
      event = null;
      let implicit = (tag === null || tag === '!');
      if (indentlessSequence && this.checkToken(BlockEntryToken)) {
        endMark = this.peekToken().endMark;
        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark);
        this.state = this.parseIndentlessSequenceEntry;
      } else if (this.checkToken(ScalarToken)) {
        const token = this.getToken();
        endMark = token.endMark;
        let scalarImplicit;
        if ((token.plain && tag === null) || tag === '!') scalarImplicit = [true, false];
        else if (tag === null) scalarImplicit = [false, true];
        else scalarImplicit = [false, false];
        event = new ScalarEvent(anchor, tag, scalarImplicit, token.value,
          startMark, endMark, token.style);
        this.state = this.states.pop();
      } else if (this.checkToken(FlowSequenceStartToken)) {
        endMark = this.peekToken().endMark;
        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, true);
        this.state = this.parseFlowSequenceFirstEntry;
      } else if (this.checkToken(FlowMappingStartToken)) {
        endMark = this.peekToken().endMark;
        event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, true);
        this.state = this.parseFlowMappingFirstKey;
      } else if (block && this.checkToken(BlockSequenceStartToken)) {
        endMark = this.peekToken().startMark;
        event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark, false);
        this.state = this.parseBlockSequenceFirstEntry;
      } else if (block && this.checkToken(BlockMappingStartToken)) {
        endMark = this.peekToken().startMark;
        event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark, false);
        this.state = this.parseBlockMappingFirstKey;
      } else if (anchor !== null || tag !== null) {
        // Empty scalars are allowed even if a tag or an anchor is specified.
