    const event = new MappingEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseBlockMappingValue() {
    if (this.checkToken(ValueToken)) {
      const token = this.getToken();
      if (!this.checkToken(KeyToken, ValueToken, BlockEndToken)) {
