  // flow_mapping_entry are equal, their interpretations are different.
  // For `flow_sequence_entry`, the part `KEY flow_node? (VALUE flow_node?)?`
  // generate an inline mapping (set syntax).

  parseFlowSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseFlowSequenceEntry(true);
  }

  parseFlowSequenceEntry(first = false) {
    if (!this.checkToken(FlowSequenceEndToken)) {
      if (!first) {
        if (this.checkToken(FlowEntryToken)) {
          this.getToken();
        } else {
          const token = this.peekToken();
          throw new ParserError('while parsing a flow sequence', this.marks[this.marks.length - 1],
            `expected ',' or ']', but got ${repr(token.id)}`, token.startMark);
        }
      }
